(() => {
  const root = document.documentElement, button = document.getElementById("theme-toggle"), icon = button.querySelector("span");
  function update(t) {
    const dark = t === "dark";
    icon.textContent = dark ? "☀" : "☾";
    button.setAttribute("aria-label", dark ? "Switch to day mode" : "Switch to night mode");
    button.setAttribute("aria-pressed", String(dark));
  }
  update(root.dataset.theme || "light");
  button.addEventListener("click", () => {
    const t = root.dataset.theme === "dark" ? "light" : "dark";
    root.dataset.theme = t; update(t);
    try { localStorage.setItem("upb-theme", t); } catch (_) {}
  });
})();
</script>
