        var(--card);
      box-shadow: var(--shadow);
    }

    .hero::after {
      position: absolute;
      right: -3.3rem;
      bottom: -7.5rem;
      width: 19rem;
      height: 19rem;
      border: 1px solid var(--border);
      border-radius: 50%;
      content: "";
      pointer-events: none;
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent-strong);
      font-size: 0.77rem;
      font-weight: 760;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .hero h1 {
      max-width: 740px;
      margin: 0;
      font-size: clamp(2.7rem, 7.5vw, 5.8rem);
      font-weight: 780;
      letter-spacing: -0.075em;
      line-height: 0.99;
    }

    .hero-copy {
      max-width: 580px;
      margin: 1.2rem 0 0;
      color: var(--muted);
      font-size: clamp(1rem, 2vw, 1.15rem);
    }

    .hero-label {
      display: inline-flex;
      width: fit-content;
      align-items: center;
      gap: 0.55rem;
      margin-top: 1.6rem;
      padding: 0.45rem 0.8rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: var(--bg);
      color: var(--muted);
      font-size: 0.8rem;
      font-weight: 630;
    }

    .hero-label::before {
      width: 0.48rem;
      height: 0.48rem;
      border-radius: 50%;
      background: var(--accent);
      content: "";
    }

    .section {
      padding-top: 5.3rem;
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1.5rem;
      margin-bottom: 1.25rem;
    }

    .section-heading h2 {
      margin: 0;
      font-size: clamp(2rem, 4.5vw, 3.25rem);
      font-weight: 740;
      letter-spacing: -0.06em;
      line-height: 1.12;
    }

    .section-intro {
      max-width: 720px;
      margin: 0 0 2rem;
      color: var(--muted);
      font-size: 1rem;
    }

    .team-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1.25rem;
    }

    .member-card {
      min-width: 0;
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 1.15rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .member-photo {
      display: block;
      width: 100%;
      height: 245px;
      object-fit: cover;
      object-position: center 38%;
      background: var(--accent-soft);
    }

    .member-body {
      padding: 1.45rem;
    }

    .member-topline {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 0.75rem;
      margin-bottom: 0.2rem;
    }

    .member-topline h3 {
      margin: 0;
      font-size: 1.55rem;
      font-weight: 750;
      letter-spacing: -0.04em;
    }

    .semester {
      color: var(--muted);
      font-size: 0.78rem;
      text-align: right;
    }

    .interests {
      margin: 0.55rem 0 1.15rem;
      color: var(--muted);
      font-size: 0.91rem;
